R=/scratch/jjyeung/orch_n30
date -u +%TZ
echo 2 > $R/sb_queue/cap
echo  | base64 -d > $R/sb_queue/codexq3.sh
tmux kill-session -t sb_codexq; tmux kill-session -t sb_rlfix2r
mkdir -p $R/sb_harev3/prompts $R/sb_harev3/out
echo  | base64 -d > $R/sb_harev3/prompts/sb_harev3.md
echo  | base64 -d > $R/sb_rlfix2/prompts/sb_rlfix2s.md
{ echo sb_harev3; cat $R/sb_queue/queue.txt; echo sb_rlfix2s:sb_rlfix2; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt
tmux new-session -d -s sb_codexq "bash $R/sb_queue/codexq3.sh"
sleep 5; cat $R/sb_queue/queue.txt | tr "\n" " "; echo
pgrep -af "codex_dispatch.sh implement $R/sb_" | grep -o "label [a-zA-Z0-9_]*" | sort -u | tr "\n" " "; echo
for s in sb_drev7 sb_rkrev2; do echo "$s log=$(wc -c < $R/$s/cursor.log) verdict=$(ls $R/$s/REVIEW_VERDICT.md 2>/dev/null)"; done
for t in sb_kbox4r sb_f64revr; do d=$(ls -d $R/codex_local/agent/scratch/codex_runs/*_$t | tail -1); echo "== $t cap=$(grep -c "at capacity" $d/transcript.log)"; head -c 600 $d/final_message.md 2>/dev/null; echo; done
